// A stand-in for jsdom with the surface Vitest's jsdom environment uses.
"use strict";

class JSDOM {
  constructor(_html, options = {}) {
    // Like a real jsdom window, a separate object that carries its own copy
    // of the platform globals.
    const window = {};
    for (
      let object = globalThis;
      object && object !== Object.prototype;
      object = Object.getPrototypeOf(object)
    ) {
      for (const key of Object.getOwnPropertyNames(object)) {
        if (key in window || key === "constructor") continue;
        try {
          const value = globalThis[key];
          window[key] = typeof value === "function" && !/^[A-Z]/.test(key)
            ? value.bind(globalThis)
            : value;
        } catch {
          // ignore getters that throw
        }
      }
    }
    window.document = { title: "stub document", defaultView: null };
    window.location = { href: options.url };
    window.close = () => {};
    this.window = window;
  }
}

class VirtualConsole {
  forwardTo() {}
}

class CookieJar {}

module.exports = { JSDOM, VirtualConsole, CookieJar };
